function solve(index, count, net) {
  if (index == requests.length) {
    if (net.every(x => x == 0)) return count;
    return 0;
  }
  // Option 1: Include request
  net[requests[index][0]]--;
  net[requests[index][1]]++;
  let res = solve(index + 1, count + 1, net);
  // Backtrack
  net[requests[index][0]]++;
  net[requests[index][1]]--;
  // Option 2: Skip request
  return Math.max(res, solve(index + 1, count, net));
}
